/**
 * Business ID — the short permanent vendor identifier (e.g. PL482913) staff type at sign-in.
 * Generated by the database (drizzle/0162_tenant_business_id.sql); this module only parses
 * and resolves it. Sign-in forms accept either the Business ID or the legacy URL slug.
 */
import { eq } from 'drizzle-orm'
import { db } from '@/lib/db'
import { tenants } from '@/lib/db/schema'

import { normalizeBusinessId } from './business-id-format'

export { normalizeBusinessId, formatBusinessId } from './business-id-format'

/**
 * Finds the tenant for a sign-in identifier: a Business ID (any spacing/case/dash) or a slug.
 * Tenants are a global table, so this uses the non-tenant connection like the login routes do.
 */
export async function findTenantByIdentifier(identifier: string) {
  const businessId = normalizeBusinessId(identifier)
  if (businessId) {
    return db.query.tenants.findFirst({ where: eq(tenants.businessId, businessId) })
  }
  const slug = identifier.trim().toLowerCase()
  if (!slug) return undefined
  return db.query.tenants.findFirst({ where: eq(tenants.slug, slug) })
}
